namespace Garethp.ModsOfMistriaInstallerLib.Seam;

/// <summary>Renders the small generated GML file that records the AIM build.</summary>
public static class InstallStampRenderer
{
    public const string Global = "__aim_installer_version";

    public static string Render(string version)
    {
        var literal = version.Replace("\\", "\\\\").Replace("\"", "\\\"");
        return string.Join("\n",
        [
            "//",
            "// mmapi_install_stamp.gml -- GENERATED BY AIM, DO NOT EDIT.",
            "// The AIM release that built this archive. Archives made by older",
            $"// installers leave global[$ \"{Global}\"] undefined.",
            "//",
            "",
            $"global.{Global} = \"{literal}\";",
            "",
        ]);
    }
}
